#pragma once

#include <QFile>
#include <QString>
#include <QThread>

class ImportThread : public QThread
{
    Q_OBJECT
public:
    explicit ImportThread(const QString &path, QObject *parent = nullptr)
        : QThread(parent), m_path(path)
    {
    }

signals:
    void progress(int percent);
    void done(int rows);

protected:
    void run() override
    {
        QFile file(m_path);
        if (!file.open(QIODevice::ReadOnly)) {
            emit done(0);
            return;
        }
        int rows = 0;
        while (!file.atEnd()) {
            file.readLine();
            ++rows;
            if (rows % 1000 == 0)
                emit progress(int(file.pos() * 100 / file.size()));
        }
        emit done(rows);
    }

private:
    QString m_path;
};

#include "mainwindow.h"

#include "import/importthread.h"

void MainWindow::startImport(const QString &path)
{
    auto *thread = new ImportThread(path, this);
    connect(thread, &ImportThread::progress, this, &MainWindow::onImportProgress);
    connect(thread, &ImportThread::done, this, &MainWindow::onImportDone);
    thread->start();
}

