#pragma once

#include <QObject>
#include <QString>

class ImportWorker : public QObject
{
    Q_OBJECT
public:
    explicit ImportWorker(QString path, QObject *parent = nullptr);

public slots:
    void process();

signals:
    void progress(int percent);
    void done(int rows);

private:
    QString m_path;
};

#include "importworker.h"

#include <utility>

#include <QFile>
#include <QThread>

ImportWorker::ImportWorker(QString path, QObject *parent)
    : QObject(parent), m_path(std::move(path))
{
}

void ImportWorker::process()
{
    QFile file(m_path);
    if (!file.open(QIODevice::ReadOnly)) {
        emit done(0);
        return;
    }
    int rows = 0;
    while (!file.atEnd()) {
        file.readLine();
        ++rows;
        if (rows % 1000 == 0)
            emit progress(int(file.pos() * 100 / file.size()));
    }
    emit done(rows);
}

void MainWindow::startImport(const QString &path)
{
    auto *thread = new QThread(this);
    auto *worker = new ImportWorker(path, this);
    worker->moveToThread(thread);

    connect(thread, &QThread::started, worker, &ImportWorker::process);
    connect(worker, &ImportWorker::progress, this, &MainWindow::onImportProgress);
    connect(worker, &ImportWorker::done, this, &MainWindow::onImportDone);
    connect(worker, &ImportWorker::done, thread, &QThread::quit);
    connect(thread, &QThread::finished, worker, &QObject::deleteLater);
    connect(thread, &QThread::finished, thread, &QObject::deleteLater);

    thread->start();
}

// mainwindow.h
QPointer<QThread> m_importThread;

// startImport, just before thread->start()
m_importThread = thread;

void MainWindow::cancelImport()
{
    if (m_importThread)
        m_importThread->requestInterruption();
}
